// Content with portions generated by generative AI platform
package org.eclipse.kura.web.session;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import javax.servlet.http.HttpSession;
import javax.servlet.http.HttpSessionBindingEvent;
import javax.servlet.http.HttpSessionBindingListener;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.eclipse.kura.audit.AuditContext;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Keeps track of the number of currently allocated sessions that did not
 * complete an authentication flow yet, in
 * order to allow bounding the amount of server side state that can be allocated
 * by unauthenticated requests.
 *
 * <p>
 * A tracked session is accounted for until it is either authenticated (see
 * {@link #release(HttpSession)}), explicitly
 * invalidated or expired. The last two cases are detected by binding a
 * {@link HttpSessionBindingListener} as a session
 * attribute, so that no container specific listener registration is required.
 * </p>
 */
public class UnauthenticatedSessionTracker {

    private final AtomicInteger trackedSessionCount = new AtomicInteger();
    private static final Logger logger = LoggerFactory.getLogger(UnauthenticatedSessionTracker.class);
    private static final Logger auditLogger = LoggerFactory.getLogger("AuditLogger");

    public TrackingToken reserveToken(final int maxCount) throws KuraException {
        return new TrackingToken(maxCount);
    }

    public boolean isTrackedOrAuthenticated(final HttpSession session) {
        return session.getAttribute(Attributes.AUTORIZED_USER.getValue()) != null
                || session.getAttribute(Attributes.UNAUTHENTICATED_SESSION.getValue()) instanceof TrackingToken;
    }

    public void release(final HttpSession session) {
        session.removeAttribute(Attributes.UNAUTHENTICATED_SESSION.getValue());
    }

    /**
     * @return the number of sessions that are currently tracked
     */
    public int getTrackedSessionCount() {
        return this.trackedSessionCount.get();
    }

    public class TrackingToken implements HttpSessionBindingListener, AutoCloseable {

        private final AtomicBoolean owner;

        public TrackingToken(final int maxCount) throws KuraException {
            this.owner = new AtomicBoolean(true);
            int current = trackedSessionCount.get();

            while (current < maxCount) {
                if (trackedSessionCount.compareAndSet(current, current + 1)) {
                    logger.debug("session token created {}, token count {}", this, current + 1);
                    return;
                }

                current = trackedSessionCount.get();
            }

            auditLogger.warn("{} UI Session - Failure - Maximum unauthenticated session limit reached",
                    AuditContext.currentOrInternal());
            throw new KuraException(KuraErrorCode.SECURITY_EXCEPTION, "Unauthenticated session limit reached");
        }

        public TrackingToken(final TrackingToken other) {
            this.owner = new AtomicBoolean(other.owner.getAndSet(false));
        }

        public void attach(final HttpSession session) {
            try {
                session.setAttribute(Attributes.UNAUTHENTICATED_SESSION.getValue(), new TrackingToken(this));
                logger.debug("session token attached {}", this);
            } catch (final Exception e) {
                this.owner.set(true);
                throw e;
            }
        }

        @Override
        public void valueBound(HttpSessionBindingEvent event) {
            // nothing to do
        }

        @Override
        public void valueUnbound(HttpSessionBindingEvent event) {
            close();
        }

        @Override
        public void close() {
            if (this.owner.getAndSet(false)) {
                int newCount = trackedSessionCount.decrementAndGet();
                logger.debug("session token released {}, token count: {}", this, newCount);
            }
        }
    }
}
